      "target_role": "log_timestamp",
      "context": null,
      "regex": "^([0-9]{8}-[0-9]{2}:[0-9]{2}:[0-9]{2}:[0-9]{3})\\|([A-Za-z0-9_]+)\\|([0-9]+)\\|([A-Za-z0-9_]+)",
      "replacement": "{placeholder}",
      "program": {
        "op": "python_exec",
        "code": "def forward(groups):\n    timestamp = groups[0]\n    context = '|'.join(groups[1:])\n    timestamp_ms = int(datetime.strptime(timestamp, '%Y%m%d-%H:%M:%S:%f').timestamp() * 1000)\n    return {'stored': [timestamp_ms], 'layout': [context]}\n\ndef inverse(record):\n    timestamp = datetime.fromtimestamp(record['stored'][0] / 1000).strftime('%Y%m%d-%H:%M:%S:%f')[:-3]\n    context = record['layout'][0]\n    return f\"{timestamp}|{context}\""
      }
    }
  ]
